package com.hotelmanagement.hms.order.model; import jakarta.persistence.*; import java.math.*; import java.util.*;
@Entity @Table(name="order_items") public class OrderItem { @Id UUID id=UUID.randomUUID(); @Column(name="hotel_id") UUID hotelId; @Column(name="branch_id") UUID branchId; @Column(name="order_id") UUID orderId; @Column(name="product_id") UUID productId; @Column(name="product_name") String productName; BigDecimal quantity,unitPrice,taxRate; String destination; @Column(name="original_currency") String originalCurrency; @Column(name="original_unit_price") BigDecimal originalUnitPrice; @Column(name="fx_rate") BigDecimal fxRate; public OrderItem currencySnapshot(String currency,BigDecimal original,BigDecimal rate){originalCurrency=currency;originalUnitPrice=original;fxRate=rate;return this;} protected OrderItem(){} public static OrderItem create(UUID h,UUID b,UUID o,UUID p,String n,BigDecimal q,BigDecimal price,BigDecimal tax,String d){var i=new OrderItem();i.hotelId=h;i.branchId=b;i.orderId=o;i.productId=p;i.productName=n;i.quantity=q;i.unitPrice=price;i.taxRate=tax;i.destination=d;return i;} public UUID getProductId(){return productId;} public BigDecimal getQuantity(){return quantity;} public BigDecimal getUnitPrice(){return unitPrice;} }
